import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Pricing card 3 label – a static plane with image texture and overlay text.
 * No cinematic primitives applied.
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // ── Plane (backdrop for texture) ──────────────────────────────
  // Based on atlas region 512×320 → aspect 1.6:1
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // fallback surface colour
    transparent: false,
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = -0.001; // behind text
  group.add(plane);

  // ── Asynchronously load the texture ──────────────────────────
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ── Text overlay ─────────────────────────────────────────────
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((item) => item.role === 'headline');
  const textContent = headline?.text ?? 'Pricing 3';

  const text = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#e8ecf2', // paper
    align: 'center',
  });
  text.position.z = 0.001; // slightly in front
  plane.add(text);

  // ── Attach event handlers (none) ─────────────────────────────
  group.userData.handlers = {};

  // ── Cleanup ──────────────────────────────────────────────────
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Dispose text resources (meshes, materials, geometries)
    text.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return group;
}
